const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '植物细胞结构示意' },
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '细胞核' },
      { kind: 'text', payload: '液泡' }
    ];
  },
  render: function (input, metrics) {
    var wall = [
      ['M', 120, 100],
      ['C', 240, 78, 500, 82, 610, 104],
      ['C', 648, 170, 642, 360, 616, 446],
      ['C', 500, 476, 250, 472, 110, 444],
      ['C', 78, 360, 80, 170, 120, 100],
      ['Z']
    ];
    var membrane = [
      ['M', 132, 120],
      ['C', 240, 100, 490, 104, 592, 124],
      ['C', 626, 182, 620, 350, 596, 426],
      ['C', 490, 454, 260, 450, 130, 426],
      ['C', 102, 350, 104, 182, 132, 120],
      ['Z']
    ];
    var vacuole = [
      ['M', 300, 220],
      ['C', 360, 190, 470, 200, 505, 255],
      ['C', 535, 305, 500, 380, 430, 392],
      ['C', 360, 405, 270, 380, 250, 320],
      ['C', 232, 270, 250, 238, 300, 220],
      ['Z']
    ];
    var nucleus = visualSdk.circle(215, 340, 62);
    var nucleolus = visualSdk.circle(230, 325, 18);
    var wallLeader = visualSdk.polyline([[560, 72], [585, 105], [610, 150]]);
    var wallDot = visualSdk.circle(610, 150, 4);
    var nucleusLeader = visualSdk.polyline([[150, 475], [175, 440], [205, 395]]);
    var nucleusDot = visualSdk.circle(205, 395, 4);
    var vacuoleLeader = visualSdk.polyline([[548, 262], [528, 278], [508, 295]]);
    var vacuoleDot = visualSdk.circle(508, 295, 4);
    return {
      schemaVersion: 1,
      sceneId: 'plant-cell-schematic',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: input.viewport.widthDu, height: input.viewport.heightDu },
      paths: [
        { id: 'wall', commands: wall },
        { id: 'membrane', commands: membrane },
        { id: 'vacuole', commands: vacuole },
        { id: 'nucleus', commands: nucleus },
        { id: 'nucleolus', commands: nucleolus },
        { id: 'wallLeader', commands: wallLeader },
        { id: 'wallDot', commands: wallDot },
        { id: 'nucleusLeader', commands: nucleusLeader },
        { id: 'nucleusDot', commands: nucleusDot },
        { id: 'vacuoleLeader', commands: vacuoleLeader },
        { id: 'vacuoleDot', commands: vacuoleDot }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'wall', fill: '#D9E8C5', stroke: { width: 8, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'membrane', fill: '#F4F9EA', stroke: { width: 3, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'vacuole', fill: '#CFE7F7', stroke: { width: 3, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'nucleus', fill: '#F4D6E3', stroke: { width: 3, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'nucleolus', fill: '#C97A9A', stroke: { width: 1, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'wallLeader', fill: '#6B8E4E', stroke: { width: 2, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'wallDot', fill: '#6B8E4E', stroke: { width: 1 } },
          { type: 'path', pathId: 'nucleusLeader', fill: '#6B8E4E', stroke: { width: 2, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'nucleusDot', fill: '#6B8E4E', stroke: { width: 1 } },
          { type: 'path', pathId: 'vacuoleLeader', fill: '#6B8E4E', stroke: { width: 2, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'vacuoleDot', fill: '#6B8E4E', stroke: { width: 1 } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: 360, y: 34 }, hAlign: 'center', vAlign: 'middle', color: '#2F4F2F' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: 560, y: 55 }, hAlign: 'center', vAlign: 'bottom', color: '#26354A' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: 140, y: 490 }, hAlign: 'center', vAlign: 'top', color: '#26354A' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: 560, y: 250 }, hAlign: 'left', vAlign: 'middle', color: '#26354A' }
        ]
      }
    };
  }
};
